var lod=t.GetComponent<LODGroup>();if(lod)lod.RecalculateBounds();var capture=typeof(CityTaxiStandBuild).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic);var controller=sc.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<CityDayNightController>(true)).FirstOrDefault();bool night=controller&&controller.IsNight;try{if(controller)controller.Apply(false);capture.Invoke(null,new object[]{sc,t.TransformPoint(new Vector3(-.25f,4.4f,24)),t.TransformPoint(new Vector3(-.25f,3.5f,10)),"GunShop-Front"});capture.Invoke(null,new object[]{sc,t.TransformPoint(new Vector3(-11,7,27)),t.TransformPoint(new Vector3(-.25f,4.5f,10)),"GunShop-Joins"});capture.Invoke(null,new object[]{sc,t.TransformPoint(new Vector3(-3,2.6f,15)),t.TransformPoint(new Vector3(-.25f,.8f,10.9f)),"GunShop-Steps"});if(controller)controller.Apply(true);capture.Invoke(null,new object[]{sc,t.TransformPoint(new Vector3(-.25f,4.3f,28)),t.TransformPoint(new Vector3(-.25f,3.4f,10)),"GunShop-Finish-Night"});}finally{if(controller)controller.Apply(night);}using(var sha=SHA256.Create())if(Convert.ToBase64String(sha.ComputeHash(File.ReadAllBytes(Atlas)))!=hash)throw new Exception("Atlas unexpectedly changed");if(t.GetComponentsInChildren<Renderer>(true).Any(r=>r.sharedMaterials.Length!=1||r.sharedMaterial!=material)||ShaderUtil.ShaderHasError(material.shader))throw new Exception("Shared material check failed");AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(sc);EditorSceneManager.SaveScene(sc);string report="SUCCESS: premium finishing pass on Gun Shop. Two correctly proportioned target emblems on fascia, matching textured wood end panels,18mm warm under-fascia/edge accents and a flush dark stone entrance threshold. Existing1.8m player scale, alignment, slope-fitting landing and access steps preserved. Same existing material and unchanged atlas (SHA256 verified), one renderer/submesh perLOD,3LODs. No new texture/material assets, separate detail objects or realtime lights. Added="+added